/* ============================================================
   أطياب الجاسم (React) — شريحة المستخدم (userSlice)
   · profile : البيانات الشخصية + العنوان (تُحفظ في atyab-profile)
   · accounts: حسابات المتجر (على الخادم: جدول Customer) — كلمة المرور
               تُخزَّن كبصمة SHA-256 مع «ملح» عشوائي، ولا تُحفظ كنصّ صريح
               أبداً، والنسخة المحلية هنا ذاكرة تشغيل سريعة فقط.
   · session : الحساب المسجَّل دخوله الآن (بريده) أو null.
   ★ التحقّق من صحّة الإدخال (إيميل/هاتف برمز دولة/عنوان/كلمة مرور) في
     src/validation.js — لا منطق تحقّق داخل هذه الشريحة.
   ============================================================ */

import { createSlice } from "@reduxjs/toolkit";
import { KEYS, readJSON, writeJSON, removeRaw } from "../persist.js";
import { normalizeRegionKey, countryByKey } from "../../data/appConfig.js";
import { isPlaceholderName, isPlaceholderPhone } from "../../validation.js";

export const BLANK_ADDRESS = {
  city: "",
  district: "",
  street: "",
  building: "",
  postal: "",
  landmark: "",
  type: "home",
  notes: "",
  isDefault: false
};

export const BLANK_PROFILE = {
  firstName: "",
  lastName: "",
  email: "",
  phone: "",
  phoneCode: "971",
  region: "AE",
  language: "ar",
  currency: "AED",
  address: BLANK_ADDRESS,
  updatedAt: 0,
  addressUpdatedAt: 0
};

/* رمز الهاتف المُخمَّن من رقم مخزّن — وإلا رمز دولة المنطقة — وإلا 971 */
function guessPhoneCode(phone, regionKey) {
  const d = String(phone == null ? "" : phone).replace(/\D/g, "");
  const codes = ["966", "971", "965", "973", "968", "974"];
  for (let i = 0; i < codes.length; i++) {
    if (d.indexOf(codes[i]) === 0 && d.length > codes[i].length) return codes[i];
  }
  const c = countryByKey(regionKey);
  return (c && c.phoneCode) || "971";
}

function cloneProfile(source) {
  const out = {};
  Object.keys(BLANK_PROFILE).forEach(function (k) {
    if (k === "address") {
      const addr = {};
      Object.keys(BLANK_ADDRESS).forEach(function (a) {
        addr[a] = source && source.address && source.address[a] != null ? source.address[a] : BLANK_ADDRESS[a];
      });
      out.address = addr;
    } else {
      out[k] = source && source[k] != null ? source[k] : BLANK_PROFILE[k];
    }
  });
  /* ★ ترحيل القيم القديمة: منطقة مخزّنة كاسم مدينة/دولة ← مفتاح دولة */
  out.region = normalizeRegionKey(out.region);
  if (!out.phoneCode) out.phoneCode = guessPhoneCode(out.phone, out.region);
  if (!out.currency) out.currency = "AED";
  if (out.region === "AE" && out.currency === "SAR") out.currency = "AED";
  /* ★ صفّ مؤقت من الخادم (عميل/جديد/…)؟ يُمسح ولا يُعرض أبداً */
  if (isPlaceholderName(out.firstName) && isPlaceholderName(out.lastName)) {
    out.firstName = "";
    out.lastName = "";
    if (isPlaceholderPhone(out.phone)) {
      out.phone = "";
      out.phoneCode = (countryByKey(out.region) || {}).phoneCode || "971";
    }
  }
  if (!out.language) out.language = "ar";
  return out;
}

/* جلسة الخادم المحفوظة (JWT) — تُقرأ عند الإقلاع ليُجدَّد بصمت */
function readAuth() {
  const customer = readJSON(KEYS.authCustomer, null);
  const access = readJSON(KEYS.authAccess, null);
  if (customer && customer.email) {
    return {
      status: "customer",
      customerId: customer.id == null ? null : customer.id,
      email: String(customer.email),
      firstName: String(customer.firstName || ""),
      expiresAt: Number((access && access.expiresAt) || 0)
    };
  }
  return { status: "guest", customerId: null, email: "", firstName: "", expiresAt: 0 };
}

const slice = createSlice({
  name: "user",
  initialState: {
    profile: cloneProfile(readJSON(KEYS.profile, null)),
    accounts: readJSON(KEYS.accounts, {}),
    session: readJSON(KEYS.session, null),
    auth: readAuth()
  },
  reducers: {
    /* تحديث جزئي: { firstName: "..." } أو { address: { city: "..." } } */
    setProfile: function (state, action) {
      const patch = action.payload || {};
      const next = cloneProfile(state.profile);
      Object.keys(patch).forEach(function (k) {
        if (k === "address") {
          Object.keys(patch.address || {}).forEach(function (a) {
            next.address[a] = patch.address[a];
          });
        } else if (k in BLANK_PROFILE) {
          next[k] = patch[k];
        }
      });
      next.updatedAt = Date.now();
      state.profile = next;
      writeJSON(KEYS.profile, next);
    },
    setAddress: function (state, action) {
      const patch = action.payload || {};
      const next = cloneProfile(state.profile);
      Object.keys(patch).forEach(function (a) {
        if (a in BLANK_ADDRESS) next.address[a] = patch[a];
      });
      next.addressUpdatedAt = Date.now();
      next.updatedAt = Date.now();
      state.profile = next;
      writeJSON(KEYS.profile, next);
    },
    /* العملة جزء من الملف الشخصي — مصدر واحد للأسعار */
    setCurrency: function (state, action) {
      const next = cloneProfile(state.profile);
      next.currency = String(action.payload || "AED").toUpperCase();
      next.updatedAt = Date.now();
      state.profile = next;
      writeJSON(KEYS.profile, next);
    },
    resetProfile: function (state) {
      const next = cloneProfile(null);
      state.profile = next;
      writeJSON(KEYS.profile, next);
    },
    /* حفظ حساب جديد (بصمة + ملح — لا كلمة مرور صريحة) */
    registerAccount: function (state, action) {
      const p = action.payload || {};
      const email = String(p.email || "").trim().toLowerCase();
      if (!email) return;
      state.accounts[email] = {
        email: email,
        firstName: String(p.firstName || ""),
        lastName: String(p.lastName || ""),
        salt: String(p.salt || ""),
        hash: String(p.hash || ""),
        createdAt: Date.now()
      };
      state.session = email;
      writeJSON(KEYS.accounts, state.accounts);
      writeJSON(KEYS.session, email);
    },
    setSession: function (state, action) {
      state.session = action.payload ? String(action.payload).trim().toLowerCase() : null;
      writeJSON(KEYS.session, state.session);
    },
    logout: function (state) {
      state.session = null;
      writeJSON(KEYS.session, null);
      state.auth = { status: "guest", customerId: null, email: "", firstName: "", expiresAt: 0 };
      removeRaw(KEYS.authAccess);
      removeRaw(KEYS.authRefresh);
      removeRaw(KEYS.authCustomer);
    },
    /* ★ جلسة الخادم (JWT): تُثبَّت بعد signup/login/refresh ناجح */
    sessionEstablished: function (state, action) {
      const p = action.payload || {};
      state.auth = {
        status: "customer",
        customerId: p.customerId == null ? null : p.customerId,
        email: String(p.email || "").trim().toLowerCase(),
        firstName: String(p.firstName || ""),
        expiresAt: Number(p.expiresAt) || 0
      };
    },
    sessionDropped: function (state) {
      state.auth = { status: "guest", customerId: null, email: "", firstName: "", expiresAt: 0 };
    }
  }
});

export const userActions = slice.actions;
export const userReducer = slice.reducer;
export const selectProfile = function (state) {
  return state.user.profile;
};
export const selectAddress = function (state) {
  return state.user.profile.address;
};
export const selectCurrencyCode = function (state) {
  return state.user.profile.currency || "AED";
};
export const selectAccounts = function (state) {
  return state.user.accounts;
};
export const selectSession = function (state) {
  return state.user.session;
};
/* وضع العميل (Customer) مقابل الزائر (Guest) — للبوابات والشارات */
export const selectAuthMode = function (state) {
  if (state.user.session) return "customer";
  if (state.user.auth && state.user.auth.status === "customer") return "customer";
  return "guest";
};
export const selectHasProfile = function (state) {
  const p = state.user.profile;
  return !!(p.firstName || p.lastName || p.email || p.phone);
};
export const selectFullName = function (state) {
  const p = state.user.profile;
  return [p.firstName, p.lastName].filter(Boolean).join(" ").trim();
};
export const selectAccount = function (state, email) {
  return state.user.accounts[String(email || "").trim().toLowerCase()] || null;
};
