/* ============================================================
   أطياب الجاسم (React) — مخزن Redux (المصدر الواحد للحقيقة)
   كل حالة الموقع هنا: المسار، الكتالوجات، المفضلة، العربة، المستخدم،
   والتقييمات. الكومبوننتات تقرأ منه ولا تُخزّن نسخة خاصة بها.
   مع مُستمع واحد يحفظ ما يجب حفظه في localStorage.
   ============================================================ */

import { configureStore } from "@reduxjs/toolkit";
import { uiReducer } from "./slices/uiSlice.js";
import { catalogReducer } from "./slices/catalogSlice.js";
import perfumesReducer from "./slices/perfumesSlice.js";
import oudsReducer from "./slices/oudsSlice.js";
import incensesReducer from "./slices/incensesSlice.js";
import imagesReducer from "./slices/imagesSlice.js";
import { wishlistReducer } from "./slices/wishlistSlice.js";
import { cartReducer } from "./slices/cartSlice.js";
import { userReducer } from "./slices/userSlice.js";
import { customerReducer } from "./slices/customerSlice.js";
import { geoReducer } from "./slices/geoSlice.js";
import { reviewsReducer } from "./slices/reviewsSlice.js";
import { ordersReducer } from "./slices/ordersSlice.js";
import { storeInfoReducer } from "./slices/storeInfoSlice.js";
import settingsReducer from "./slices/settingsSlice.js";
import profilesReducer from "./slices/productProfilesSlice.js";
import { offersReducer } from "./slices/offersSlice.js";
import { eventsReducer } from "./slices/eventsSlice.js";
import { KEYS, writeJSON, writeRaw } from "./persist.js";

export const store = configureStore({
  reducer: {
    ui: uiReducer,
    catalog: catalogReducer,
    perfumes: perfumesReducer,
    ouds: oudsReducer,
    incenses: incensesReducer,
    images: imagesReducer,
    wishlist: wishlistReducer,
    cart: cartReducer,
    user: userReducer,
    customer: customerReducer,
    geo: geoReducer,
    reviews: reviewsReducer,
    orders: ordersReducer,
    storeInfo: storeInfoReducer,
    settings: settingsReducer,
    profiles: profilesReducer,
    offers: offersReducer,
    events: eventsReducer
  },
  middleware: function (getDefault) {
    return getDefault({ serializableCheck: false, immutableCheck: false });
  }
});

/* ------------------------------------------------------------
   الحفظ: نكتب فقط عند تغيّر فعلي (مقارنة نصّية) — فلا كتابة لكل نقرة
   ★ الشرائح تكتب المفضلة/المستخدم/التقييمات/الوضع/اللغة بنفسها،
     وما يتبقّى هنا هو العربة والكوبون.
   ------------------------------------------------------------ */
const last = { cart: "", coupon: "", wishlist: "" };

function persist() {
  const state = store.getState();
  const cart = JSON.stringify(state.cart.rows);
  if (cart !== last.cart) {
    last.cart = cart;
    writeJSON(KEYS.cart, state.cart.rows);
  }
  if (state.cart.coupon !== last.coupon) {
    last.coupon = state.cart.coupon;
    if (state.cart.coupon) writeRaw(KEYS.coupon, state.cart.coupon);
    else writeRaw(KEYS.coupon, "");
  }
  /* ★ المفضلة: تُحفظ هنا (الشريحة نفسها لا تكتب) — وإلا ضاعت عند التحديث */
  const wish = JSON.stringify(state.wishlist.ids);
  if (wish !== last.wishlist) {
    last.wishlist = wish;
    writeJSON(KEYS.wishlist, state.wishlist.ids);
  }
}

store.subscribe(persist);
persist();

/* للتصحيح فقط: يُتاح المخزن على النافذة في وضع التطوير */
if (typeof window !== "undefined") {
  window.__ATYAB_STORE__ = store;
}

export default store;
