/* ============================================================
   أطياب الجاسم (React) — عميل الدفع (PayTabs — صفحة مستضافة)

   العقد الوحيد المعتمد (FRONTEND_CONTRACT §10 — بلا /session نهائياً):
     · إنشاء الطلب أولاً: POST /api/orders/{id}
       ← { locationId, deliveryMethodId, paymentMethodId,
           couponCode?, customerNote?, termsAccepted:true }
       → { orderId, ...فاتورة الخادم } (الطريقة إلكترونية).
     · بدء الدفع: POST /api/payments/{id}/start ← { orderId }
       → { paymentUrl, tranRef, cartId }
       ثم توجيه كامل للمتصفح إلى paymentUrl.
     · صفحة العودة: GET /api/payments/{id}/status?cartId=
       → { status, orderId, invoiceNumber, grandTotal, tranRef } —
       تُستطلع كل ~3 ثوانٍ حتى ~60 ثانية. 409 بعد الدفع تعني غالباً
       أن الـcallback سوّاها — يُعاد قراءة تفاصيل الطلب.
     · مُتقاعَد — ممنوع: POST .../session،
       GET .../attempts/{merchantReference}، POST .../confirm.
     · بارامتر الرابط للعرض فقط (?cartId=) — الحُكم من الـ status حصراً.
       لا paymentUrl مرتين لنفس الطلب: عند إغلاق التبويب يُستعلَم
       status أولاً، ولا start جديد إلا وهي غير مدفوعة.
   ============================================================ */

import { ENDPOINTS, apiError } from "../redux/api.js";
import { authFetch } from "./auth.js";

const PENDING_KEY = "atyab:pendingPayment";

async function readJson(res) {
  const text = await res.text().catch(function () { return ""; });
  if (!text) return null;
  try { return JSON.parse(text); } catch (e) { return null; }
}

function throwPay(res, payload) {
  const d = payload || {};
  /* ★ detail العربية أولاً — مغلّف الخطأ الموحّد (§0) */
  const msg = (d.detail || d.message || d.title) || ("استجابة الخادم: " + res.status);
  const err = apiError(msg, res.status);
  err.response = { status: res.status, data: payload };
  throw err;
}

/* ---------- الاستعلام الوحيد لصفحة العودة ---------- */

/* بدء الدفع لطلب قائم: POST /api/payments/{id}/start ← { orderId }
   → { paymentUrl, tranRef, cartId } — المسار الوحيد للدفع. */
export async function startServerPayment(customerId, orderId) {
  const res = await authFetch(ENDPOINTS.paymentStart(customerId), {
    method: "POST",
    body: { orderId: Number(orderId) }
  });
  const payload = await readJson(res);
  if (!res.ok) throwPay(res, payload);
  return payload || {};
}

export async function getPaymentStatus(customerId, cartId) {
  const res = await authFetch(
    ENDPOINTS.paymentStatus(customerId) + "?cartId=" + encodeURIComponent(String(cartId || "")),
    { method: "GET" }
  );
  const payload = await readJson(res);
  if (!res.ok) throwPay(res, payload);
  return payload || {};
}

/* دفعة معلّقة — cartId هو المرجع الأول (§10)، وtranRef/orderId احتياط */
export function savePendingPayment(p) {
  try {
    window.localStorage.setItem(PENDING_KEY, JSON.stringify(p || {}));
  } catch (e) {}
}
export function readPendingPayment() {
  try {
    const raw = window.localStorage.getItem(PENDING_KEY);
    const o = raw ? JSON.parse(raw) : null;
    return o && typeof o === "object" ? o : null;
  } catch (e) {
    return null;
  }
}

export function clearPendingPayment() {
  try {
    window.localStorage.removeItem(PENDING_KEY);
  } catch (e) {}
}

/* ---------- إعداد الدفع الموجّه (صفحة الانتظار الوسيطة) ----------
   Checkout تحفظ هنا حقول إنشاء الطلب + الطريقة + العميل، ثم تنتقل
   إلى #/payment/start التي تنشئ الطلب ثم تبدأ الدفع وتغادر إلى PayTabs.
   localStorage (لا state التنقل وحده) حتى تنجو من التحديث. */
const SETUP_KEY = "atyab:paymentSetup";

export function savePaymentSetup(s) {
  try {
    window.localStorage.setItem(SETUP_KEY, JSON.stringify(s || {}));
  } catch (e) {}
}

export function readPaymentSetup() {
  try {
    const raw = window.localStorage.getItem(SETUP_KEY);
    const o = raw ? JSON.parse(raw) : null;
    return o && typeof o === "object" ? o : null;
  } catch (e) {
    return null;
  }
}

export function clearPaymentSetup() {
  try {
    window.localStorage.removeItem(SETUP_KEY);
  } catch (e) {}
}
