/* ============================================================
   أطياب الجاسم (React) — شريحة التقييمات (reviewsSlice)

   ★ هنا تُحفظ تقييمات العملاء (بديل comments-plugin في نسخة React):
     كل تقييم يُخزَّن محلياً في localStorage بالمفتاح atyab-reviews.

   ★ تُحفظ هنا تقييمات العملاء الحقيقية فقط — بلا أي توليد تجريبي.
     كومبوننت UserRate يبني إحصائيات النجوم من هذه القائمة وحدها.

   المفاتيح:
     «atyab-product-<id>»  تقييمات منتج واحد
     «atyab-store-reviews» / «atyab-incense-reviews»  تقييمات المتجر
   ============================================================ */

import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import { KEYS, readJSON, writeJSON, removeRaw } from "../persist.js";
import { api, apiUrl, ENDPOINTS, atyabLog } from "../api.js";
import { authFetch, loadSession, accessValid, refreshUsable } from "../../api/auth.js";
import { ATYAB_byId } from "../../data/products.js";

export function productKey(id) {
  return "atyab-product-" + Number(id);
}
export const STORE_KEY_PERFUMES = "atyab-store-reviews";
export const STORE_KEY_INCENSE = "atyab-incense-reviews";
export const STORE_KEY_OUDS = "atyab-oud-reviews";
export const STORE_KEY_HOME = "atyab-home-reviews";

/* ★ قناة الصفحة ← endpoint الخادم (أفضل 20). قنوات المنتجات محلية فقط. */
const SERVER_SOURCES = {
  "atyab-home-reviews": "reviewsHome",
  "atyab-store-reviews": "reviewsPerfumes",
  "atyab-oud-reviews": "reviewsOuds",
  "atyab-incense-reviews": "reviewsIncenses"
};

function fmtDate(iso) {
  const s = String(iso || "").slice(0, 10);
  return s || "";
}

/* تطبيع تقييم الخادم إلى شكل بطاقة UserComment */
export function normalizeServerReview(r) {
  const id = r && (r.reviewId != null ? r.reviewId : r.id);
  /* ★ ردّ المتجر: نلتقط كل التسميات المحتملة (Reply/ReplyAr/ReplyAt)
     — الباكند سيضيفها قريباً، والكود جاهز لها من الآن */
  function pick(keys) {
    for (let i = 0; i < keys.length; i++) {
      const v = r && r[keys[i]];
      if (v != null && String(v).trim()) return String(v).trim();
    }
    return "";
  }
  return {
    id: "srv-" + id,
    name: String((r && (r.customerName || r.name)) || "عميل أطياب").trim() || "عميل أطياب",
    rating: Math.max(1, Math.min(5, Math.round(Number((r && (r.rating != null ? r.rating : r.stars))) || 5))),
    date: fmtDate(r && (r.createdAt || r.date)),
    verified: true,
    helpful: Number((r && (r.helpfulCount != null ? r.helpfulCount : r.helpful))) || 0,
    text: String((r && (r.body || r.text)) || "").trim(),
    title: String((r && (r.title || "")) || "").trim(),
    productId: (r && (r.productId != null ? Number(r.productId) : null)) || null,
    scope: String((r && r.scope) || ""),
    catalogKey: String((r && r.catalogKey) || ""),
    reply: pick(["reply", "replyAr", "replyArabic", "storeReply", "adminReply", "response", "answer"]),
    replyEn: pick(["replyEn", "replyEnglish", "storeReplyEn", "adminReplyEn"]),
    replyAt: fmtDate(pick(["replyAt", "repliedAt", "responseAt", "answeredAt"]))
  };
}

/* ★ دمج بلا تكرار: تقييمك المحلي يُخفى متى ظهر مثيله في الخادم
   (نفس الاسم + نفس النص) — فلا يظهر التعليق الواحد مرتين أبداً */
function normKey(s) {
  return String(s == null ? "" : s).trim().replace(/\s+/g, " ").toLowerCase();
}
export function mergeUnique(own, server) {
  const list = Array.isArray(server) ? server : [];
  const seen = {};
  list.forEach(function (c) {
    seen[normKey(c && c.name) + "|" + normKey(c && c.text)] = 1;
  });
  const fresh = (Array.isArray(own) ? own : []).filter(function (c) {
    return !seen[normKey(c && c.name) + "|" + normKey(c && c.text)];
  });
  return fresh.concat(list);
}

export function getServerReviews(channelKey) {
  const src = SERVER_SOURCES[String(channelKey || "")];
  if (!src) return null;
  return fetchServerReviews({ key: String(channelKey), path: ENDPOINTS[src] });
}

export const fetchServerReviews = createAsyncThunk(
  "reviews/server",
  async function (arg, { rejectWithValue }) {
    try {
      atyabLog("reviews FETCH", arg.key);
      const res = await api.get(apiUrl(arg.path));
      const list = Array.isArray(res.data) ? res.data : asListSafe(res.data);
      atyabLog("reviews CACHED", arg.key, list.length);
      return { key: arg.key, items: list.filter(function (r) { return !r || r.isApproved !== false; }).map(normalizeServerReview).filter(function (c) { return c.text; }) };
    } catch (err) {
      atyabLog("reviews FAIL", arg.key);
      return rejectWithValue({ key: arg.key });
    }
  },
  {
    condition: function (arg, { getState }) {
      const s = getState().reviews.server[arg.key];
      if (s && (s.status === "loading" || s.status === "succeeded")) { atyabLog("reviews CACHE-HIT", arg.key); return false; }
      return true;
    }
  }
);

function asListSafe(payload) {
  if (Array.isArray(payload)) return payload;
  if (payload && Array.isArray(payload.data)) return payload.data;
  if (payload && Array.isArray(payload.items)) return payload.items;
  if (payload && Array.isArray(payload.reviews)) return payload.reviews;
  return [];
}

/* ★ تقييمات منتج واحد: GET /api/products/{id}/reviews — لكل منتج قناته */
export function getProductReviews(productId) {
  const id = Number(productId) || 0;
  if (!id) return null;
  return fetchProductReviews({ id: id, path: ENDPOINTS.productReviews(id) });
}

export const fetchProductReviews = createAsyncThunk(
  "reviews/product",
  async function (arg, { rejectWithValue }) {
    try {
      async function tryGet(path) {
        try {
          const res = await api.get(apiUrl(path));
          const raw = res && res.data != null ? res.data : null;
          return Array.isArray(raw) ? raw : asListSafe(raw);
        } catch (e) { return null; }
      }
      atyabLog("reviews FETCH product", arg.id);
      let list = await tryGet(arg.path);
      if (!list) {
        /* ★ لا GET مخصص في الباكند؟ نأخذ GET القسم ونصفّي بـ productId */
        let cat = ENDPOINTS.reviewsPerfumes;
        try {
          const p = ATYAB_byId ? ATYAB_byId(Number(arg.id)) : null;
          const k = p && p.kind;
          cat = k === "oud" ? ENDPOINTS.reviewsOuds : k === "incense" ? ENDPOINTS.reviewsIncenses : ENDPOINTS.reviewsPerfumes;
        } catch (e) {}
        const all = await tryGet(cat);
        list = all ? all.filter(function (r) { return r && Number(r.productId) === Number(arg.id); }) : [];
        atyabLog("reviews FALLBACK catalog-filter product", arg.id, list.length);
      } else {
        atyabLog("reviews CACHED product", arg.id, list.length);
      }
      return { id: arg.id, items: list.filter(function (r) { return !r || r.isApproved !== false; }).map(normalizeServerReview).filter(function (c) { return c.text; }) };
    } catch (err) {
      atyabLog("reviews FAIL product", arg.id);
      return rejectWithValue({ id: arg.id });
    }
  },
  {
    condition: function (arg, { getState }) {
      const s = getState().reviews.product[arg.id];
      if (s && (s.status === "loading" || s.status === "succeeded")) { atyabLog("reviews CACHE-HIT product", arg.id); return false; }
      return true;
    }
  }
);

/* مفتاح تقييمات أي شيء: منتج موجود → مفتاحه، وإلا تقييمات المتجر.
   (كانت في UserRate.jsx — نقلناها هنا لأن هذا ملف منطق لا مكوّنات.) */
export function rateKeyFor(id) {
  const p = ATYAB_byId ? ATYAB_byId(Number(id)) : null;
  return p ? productKey(id) : STORE_KEY_PERFUMES;
}

/* ---------- النشر على الخادم (JWT عبر authFetch) ----------
   · صفحة كتالوج → POST /api/reviews/store مع catalogKey
   · صفحة منتج  → POST /api/reviews/product/{id} بلا catalogKey
   النار-وانسِ: التقييم يُحفظ محلياً فوراً (addComment) ويظهر مباشرة،
   والـ POST في الخلفية للنشر للجميع — فلا انتظار ولا فقدان عند 401. */

const STORE_CATALOG_KEY = {
  "atyab-store-reviews": "perfumes",
  "atyab-oud-reviews": "ouds",
  "atyab-incense-reviews": "incenses",
  "atyab-home-reviews": "store"
};

export function catalogKeyFor(channelKey, fallback) {
  const k = STORE_CATALOG_KEY[String(channelKey || "")];
  if (k) return k;
  const f = String(fallback || "").toLowerCase();
  if (f === "incense") return "incenses";
  if (f === "ouds") return "ouds";
  if (f === "perfumes") return "perfumes";
  return "store";
}

async function readJsonSafe(res) {
  try {
    const t = await res.text();
    return t ? JSON.parse(t) : null;
  } catch (e) { return null; }
}

function reviewBody(arg) {
  const text = String((arg && (arg.text != null ? arg.text : arg.body)) || "").trim();
  /* ★ العقد الدقيق (§8): { rating, body } فقط — بلا title.
     ASP.NET يتجاهل الحقول الزائدة عادة، لكن «الأسماء الدقيقة»
     تعني أننا لا نرسل إلا ما طُلب. العنوان يبقى عرضاً محلياً فقط. */
  return {
    rating: Math.max(1, Math.min(5, Math.round(Number(arg && arg.rating) || 5))),
    body: text
  };
}

export const submitStoreReview = createAsyncThunk(
  "reviews/submitStore",
  async function (arg) {
    const body = reviewBody(arg);
    body.catalogKey = String((arg && arg.catalogKey) || "store");
    const res = await authFetch(ENDPOINTS.reviewPostStore, { method: "POST", body: body });
    const payload = await readJsonSafe(res);
    if (!res.ok) {
      const d = payload || {};
      const err = new Error((d.detail || d.message || d.title) || ("استجابة الخادم: " + res.status));
      err.status = res.status;
      throw err;
    }
    atyabLog("reviews POST store ok");
    return { key: arg && arg.key, saved: payload };
  }
);

export const submitProductReview = createAsyncThunk(
  "reviews/submitProduct",
  async function (arg) {
    const res = await authFetch(ENDPOINTS.reviewPostProduct(Number(arg && arg.productId)), {
      method: "POST",
      body: reviewBody(arg)
    });
    const payload = await readJsonSafe(res);
    if (!res.ok) {
      const d = payload || {};
      const err = new Error((d.detail || d.message || d.title) || ("استجابة الخادم: " + res.status));
      err.status = res.status;
      throw err;
    }
    atyabLog("reviews POST product ok", Number(arg && arg.productId));
    return { id: Number(arg && arg.productId), saved: payload };
  }
);

/* ---------- مسودة معلّقة: ضيف كتب تقييماً قبل الدخول ----------
   تُحفظ محلياً، وبعد الدخول والعودة لنفس المنتج تُنشر تلقائياً. */
const DRAFT_KEY = KEYS.reviewDraft || "atyab-pending-review";

export function savePendingReview(d) {
  try { writeJSON(DRAFT_KEY, d); } catch (e) {}
}

export function readPendingReview() {
  try {
    const d = readJSON(DRAFT_KEY, null);
    return d && typeof d === "object" ? d : null;
  } catch (e) { return null; }
}

export function clearPendingReview() {
  try { removeRaw(DRAFT_KEY); } catch (e) {}
}

/* هل يوجد توكن صالح للنشر؟ (access سارٍ أو refresh قابل للتجديد) */
export function tokenUsable() {
  try {
    const s = loadSession();
    return !!(accessValid(s.access) || refreshUsable(s.refresh));
  } catch (e) { return false; }
}

/* ---------- الشريحة ---------- */
const slice = createSlice({
  name: "reviews",
  initialState: {
    /* { [key]: [تقييم العميل...] } */
    own: readJSON(KEYS.reviews, {}) || {},
    /* { [key]: { items, status, error } } — تقييمات الخادم لكل صفحة */
    server: {},
    /* { [productId]: { items, status, error } } — تقييمات كل منتج */
    product: {}
  },
  reducers: {
    addComment: function (state, action) {
      const p = action.payload || {};
      const key = String(p.key || "");
      if (!key) return;
      const name = String(p.name || "عميل أطياب").trim() || "عميل أطياب";
      const list = state.own[key] || (state.own[key] = []);
      list.unshift({
        id: "own-" + Date.now() + "-" + Math.floor(Math.random() * 1000),
        name: name,
        rating: Math.max(1, Math.min(5, Math.round(Number(p.rating) || 5))),
        date: "الآن",
        verified: false,
        helpful: 0,
        text: String(p.text || "").trim(),
        reply: ""
      });
      writeJSON(KEYS.reviews, state.own);
    },
    markHelpful: function (state, action) {
      const p = action.payload || {};
      const key = String(p.key || "");
      const list = state.own[key];
      if (!list) return;
      list.forEach(function (c) {
        if (c.id === p.id) c.helpful = (Number(c.helpful) || 0) + 1;
      });
      writeJSON(KEYS.reviews, state.own);
    },
    removeComment: function (state, action) {
      const p = action.payload || {};
      const key = String(p.key || "");
      const list = state.own[key];
      if (!list) return;
      state.own[key] = list.filter(function (c) {
        return c.id !== p.id;
      });
      writeJSON(KEYS.reviews, state.own);
    },
    resetReviews: function (state) {
      state.own = {};
      writeJSON(KEYS.reviews, state.own);
    }
  },
  extraReducers: function (builder) {
    builder
      .addCase(fetchServerReviews.pending, function (state, action) {
        const key = action.meta.arg.key;
        state.server[key] = { items: (state.server[key] && state.server[key].items) || [], status: "loading", error: "" };
      })
      .addCase(fetchServerReviews.fulfilled, function (state, action) {
        state.server[action.payload.key] = { items: action.payload.items, status: "succeeded", error: "" };
      })
      .addCase(fetchServerReviews.rejected, function (state, action) {
        const key = (action.payload && action.payload.key) || (action.meta.arg && action.meta.arg.key) || "";
        if (key) state.server[key] = { items: (state.server[key] && state.server[key].items) || [], status: "failed", error: "fail" };
      })
      .addCase(fetchProductReviews.pending, function (state, action) {
        const id = action.meta.arg.id;
        state.product[id] = { items: (state.product[id] && state.product[id].items) || [], status: "loading", error: "" };
      })
      .addCase(fetchProductReviews.fulfilled, function (state, action) {
        state.product[action.payload.id] = { items: action.payload.items, status: "succeeded", error: "" };
      })
      .addCase(fetchProductReviews.rejected, function (state, action) {
        const id = (action.payload && action.payload.id) || (action.meta.arg && action.meta.arg.id) || 0;
        if (id) state.product[id] = { items: (state.product[id] && state.product[id].items) || [], status: "failed", error: "fail" };
      });
  }
});

export const reviewsActions = slice.actions;
export const reviewsReducer = slice.reducer;
export const selectOwnComments = function (state) {
  return state.reviews.own;
};

const EMPTY_LIST = [];

export function selectServerComments(state, key) {
  const s = state.reviews.server[key];
  return (s && s.items) || EMPTY_LIST;
}

export function selectServerStatus(state, key) {
  const s = state.reviews.server[key];
  return (s && s.status) || "idle";
}

export function selectProductComments(state, id) {
  const s = state.reviews.product[Number(id)];
  return (s && s.items) || EMPTY_LIST;
}

export function selectProductStatus(state, id) {
  const s = state.reviews.product[Number(id)];
  return (s && s.status) || "idle";
}

/* إحصاء النجوم: كم خمس؟ كم أربع؟ … + المتوسط + العدد */
export function statsOf(comments) {
  const dist = [0, 0, 0, 0, 0]; /* [5★, 4★, 3★, 2★, 1★] */
  let sum = 0;
  (comments || []).forEach(function (c) {
    const star = Math.max(1, Math.min(5, Math.round(Number(c.rating) || 0)));
    if (!star) return;
    dist[5 - star] += 1;
    sum += star;
  });
  const total = dist.reduce(function (a, b) {
    return a + b;
  }, 0);
  return {
    dist: dist,
    total: total,
    average: total ? sum / total : 0,
    percent: dist.map(function (n) {
      return total ? Math.round((n / total) * 100) : 0;
    })
  };
}
