/* ============================================================
   أطياب الجاسم (React) — شريحة الواجهة (uiSlice)

   المسؤوليات:
     · الوضع الليلي/النهاري + لغة الواجهة (محفوظان في localStorage)
     · قائمة الجوال · التنبيهات (Toast) · نافذة «قصة المنتج»

   ★ المسار لم يبقَ هنا: الراوتر (react-router-dom) هو مصدر الحقيقة
     للمسار، وكل صفحة تقرأ مسارها من الرابط (useParams/useLocation).
     هذا القسم كان يحمل parseRoute/hashOf — وقد أُزيل بالكامل.
   ============================================================ */

import { createSlice } from "@reduxjs/toolkit";
import { KEYS, readEnum, writeRaw } from "../persist.js";

function readTheme() {
  return readEnum(KEYS.theme, ["day", "night"], "day");
}

function readLanguage() {
  return readEnum(KEYS.language, ["ar", "en"], "ar");
}

function applyTheme(theme) {
  try {
    document.documentElement.setAttribute("data-theme", theme);
  } catch (e) {
    /* بيئة بلا DOM (اختبار) */
  }
}

function applyLanguage(language) {
  try {
    const root = document.documentElement;
    root.setAttribute("lang", language);
    root.setAttribute("data-lang", language);
    root.setAttribute("dir", language === "en" ? "ltr" : "rtl");
  } catch (e) {
    /* بيئة بلا DOM */
  }
}

/* نبضة التنبيهات: كل تنبيه يحمل معرّفاً حتى يُعاد تشغيل الأنيميشن */
let toastSeq = 0;

const initialState = {
  theme: readTheme(),
  language: readLanguage(),
  mobileNavOpen: false,
  storyProductId: null, /* شاشة «قصة المنتج» المنبثقة */
  toast: null /* { id, text } */
};

applyTheme(initialState.theme);
applyLanguage(initialState.language);

const slice = createSlice({
  name: "ui",
  initialState: initialState,
  reducers: {
    setTheme: function (state, action) {
      const theme = action.payload === "night" ? "night" : "day";
      state.theme = theme;
      writeRaw(KEYS.theme, theme);
      applyTheme(theme);
    },
    toggleTheme: function (state) {
      const theme = state.theme === "day" ? "night" : "day";
      state.theme = theme;
      writeRaw(KEYS.theme, theme);
      applyTheme(theme);
    },
    setLanguage: function (state, action) {
      const language = action.payload === "en" ? "en" : "ar";
      state.language = language;
      writeRaw(KEYS.language, language);
      applyLanguage(language);
    },
    setMobileNav: function (state, action) {
      state.mobileNavOpen = !!action.payload;
    },
    openStory: function (state, action) {
      state.storyProductId = Number(action.payload) || null;
    },
    closeStory: function (state) {
      state.storyProductId = null;
    },
    /* التنبيهات: نصّ واحد يظهر أسفل الشاشة ٢.٦ ثانية */
    toastShown: function (state, action) {
      toastSeq += 1;
      state.toast = { id: toastSeq, text: String(action.payload || "") };
    },
    toastCleared: function (state) {
      state.toast = null;
    }
  }
});

export const uiActions = slice.actions;
export const uiReducer = slice.reducer;
export const selectTheme = function (state) {
  return state.ui.theme;
};
export const selectLanguage = function (state) {
  return state.ui.language;
};
export const selectMobileNav = function (state) {
  return state.ui.mobileNavOpen;
};
export const selectToast = function (state) {
  return state.ui.toast;
};
export const selectStoryProductId = function (state) {
  return state.ui.storyProductId;
};
