/* ============================================================
   أطياب الجاسم (React) — التحقّق من صحّة الإدخال (validation)

   غرض هذا الملف الوحيد: التأكّد أن ما يدخله العميل صحيح قبل الحفظ.
   لا React هنا ولا Redux — دوال خالصة (pure) قابلة للاختبار وحدها،
   تستدعيها الكومبوننتات عند الحفظ/الإرسال.

   ما يُتحقَّق منه:
     · الإيميل        → صيغة صحيحة + نطاق معقول
     · كلمة المرور    → ٨ خانات على الأقل (والقوية ١٢+) بحرفين ورقم
     · الهاتف         → خليجي برمز دولة صريح (isValidPhoneFor) أو تخمين ذكي (isValidPhone)
     · الاسم          → حرفان على الأقل، حروف فقط (عربي/إنجليزي)
     · العنوان        → المدينة، الحي، الشارع، رقم المبنى، الرمز البريدي (٥ أرقام)
     · الرمز البريدي  → ٥ خانات (السعودية) — ودول الخليج بحسب طولها
     · نصّ التقييم    → ٨ أحرف على الأقل، ونجمة من ١ إلى ٥
     · رسالة التواصل  → ١٠ أحرف على الأقل

   كل دالة ترجع: { valid, errors: { field: "رسالة عربية" }, firstError }
   ============================================================ */

/* ------------------------------------------------------------
   تطبيع المدخلات (أرقام عربية ← لاتينية، وحذف المسافات الزائدة)
   ------------------------------------------------------------ */
export function normalizeDigits(value) {
  return String(value == null ? "" : value).replace(/[\u0660-\u0669\u06F0-\u06F9]/g, function (d) {
    return String(d.charCodeAt(0) & 0xf);
  });
}

export function cleanText(value) {
  return normalizeDigits(value).replace(/\s+/g, " ").trim();
}

export function digitsOnly(value) {
  return normalizeDigits(value).replace(/\D/g, "");
}

/* ------------------------------------------------------------
   الإيميل
   ------------------------------------------------------------ */
const EMAIL_RE = /^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$/;

export function isValidEmail(value) {
  const email = cleanText(value).toLowerCase();
  if (!email || email.length > 120) return false;
  if (email.indexOf("..") !== -1) return false;
  if (email.charAt(0) === "." || email.charAt(0) === "@") return false;
  return EMAIL_RE.test(email);
}

/* ------------------------------------------------------------
   كلمة المرور
   السياسة:
     · ٨ خانات كحدّ أدنى (المقترح ١٢ خانة أو أكثر = «قوية»)
     · حرفان على الأقل + رقم واحد على الأقل
     · لا مسافات، ولا كلمات ضعيفة شائعة (123456 · password …)
   ------------------------------------------------------------ */
export const PASSWORD_MIN = 8;
export const PASSWORD_STRONG = 12;

const WEAK_PASSWORDS = [
  "password", "123456", "12345678", "123456789", "qwerty", "111111",
  "abc123", "iloveyou", "admin", "000000", "123123", "atyab123"
];

export function passwordIssues(value) {
  const pw = String(value == null ? "" : value);
  const issues = [];
  if (!pw) {
    issues.push("كلمة المرور مطلوبة.");
    return issues;
  }
  if (/\s/.test(pw)) issues.push("لا تُستخدم المسافات داخل كلمة المرور.");
  if (pw.length < PASSWORD_MIN) issues.push("كلمة المرور قصيرة — يجب ألا تقلّ عن " + PASSWORD_MIN + " خانات، والأفضل " + PASSWORD_STRONG + " أو أكثر.");
  const letters = (pw.match(/[A-Za-z\u0621-\u064A]/g) || []).length;
  const numbers = (pw.match(/\d/g) || []).length;
  if (letters < 2) issues.push("أضف حرفين على الأقل.");
  if (numbers < 1) issues.push("أضف رقماً واحداً على الأقل.");
  if (WEAK_PASSWORDS.indexOf(pw.toLowerCase()) !== -1) issues.push("كلمة المرور شائعة جداً — اختر غيرها.");
  return issues;
}

export function isValidPassword(value) {
  return passwordIssues(value).length === 0;
}

/* قوّة كلمة المرور: 0 ضعيفة · 1 متوسطة · 2 قوية */
export function passwordStrength(value) {
  const pw = String(value == null ? "" : value);
  if (!isValidPassword(pw)) return 0;
  const letters = (pw.match(/[A-Za-z\u0621-\u064A]/g) || []).length;
  const numbers = (pw.match(/\d/g) || []).length;
  const symbols = (pw.match(/[^A-Za-z0-9\u0621-\u064A]/g) || []).length;
  if (pw.length >= PASSWORD_STRONG && letters >= 4 && numbers >= 2 && symbols >= 1) return 2;
  if (pw.length >= PASSWORD_STRONG || symbols >= 1 || numbers >= 2) return 2;
  return 1;
}

export function passwordStrengthLabel(value) {
  const s = passwordStrength(value);
  return s === 2 ? "قوية" : s === 1 ? "متوسطة" : "ضعيفة";
}

/* ------------------------------------------------------------
   الهاتف: سعودي 05xxxxxxxx (أو +9665…) وخليجي (+971 50… إلخ)
   ------------------------------------------------------------ */
const PHONE_RULES = [
  { code: "966", local: /^5\d{8}$/ }, /* السعودية */
  { code: "971", local: /^5\d{8}$/ }, /* الإمارات */
  { code: "965", local: /^[569]\d{7}$/ }, /* الكويت */
  { code: "973", local: /^3\d{7}$/ }, /* البحرين */
  { code: "968", local: /^[79]\d{7}$/ }, /* عمان */
  { code: "974", local: /^[3567]\d{7}$/ } /* قطر */
];

export function normalizePhone(value) {
  let d = digitsOnly(value);
  if (d.indexOf("00") === 0) d = d.slice(2);
  return d;
}

/* ------------------------------------------------------------
   الهاتف برقم دولة صريح: (code + local) — يُستعمل في «حسابي»
   حيث يختار العميل مصدر الهاتف من قائمة، والرقم المحلي وحده.
   isValidPhone القديمة تبقى للضيوف (الدفع/التواصل) بلا رمز مختار.
   ------------------------------------------------------------ */
export function phoneLocalDigits(code, value) {
  let d = digitsOnly(value);
  const c = digitsOnly(code);
  if (c && d.indexOf(c) === 0) d = d.slice(c.length);
  return d.replace(/^0+/, "");
}

export function isValidPhoneFor(code, value) {
  const d = phoneLocalDigits(code, value);
  if (!d) return false;
  const c = digitsOnly(code);
  for (let i = 0; i < PHONE_RULES.length; i++) {
    if (PHONE_RULES[i].code === c) return PHONE_RULES[i].local.test(d);
  }
  return d.length >= 7 && d.length <= 12;
}

/* الرقم الكامل للتخزين: رمز الدولة + المحلي (أرقام لاتينية بلا +) */
export function joinPhone(code, value) {
  const c = digitsOnly(code);
  const d = phoneLocalDigits(code, value);
  return c && d ? c + d : "";
}

/* تقسيم رقم مخزّن إلى {code, local} — للعرض في نموذج «حسابي» */
export function splitPhone(saved, fallbackCode) {
  let d = digitsOnly(saved);
  if (d.indexOf("00") === 0) d = d.slice(2);
  for (let i = 0; i < PHONE_RULES.length; i++) {
    const c = PHONE_RULES[i].code;
    if (d.indexOf(c) === 0 && d.length > c.length) {
      return { code: c, local: d.slice(c.length).replace(/^0+/, "") };
    }
  }
  return { code: digitsOnly(fallbackCode) || "971", local: d.replace(/^0+/, "") };
}

export function isValidPhone(value) {
  const d = normalizePhone(value);
  if (!d) return false;
  for (let i = 0; i < PHONE_RULES.length; i++) {
    const rule = PHONE_RULES[i];
    if (d.indexOf(rule.code) === 0) return rule.local.test(d.slice(rule.code.length));
  }
  /* بلا رمز دولة: نعتبره سعودياً محلّياً */
  return /^05\d{8}$/.test(d) || /^5\d{8}$/.test(d);
}

/* ------------------------------------------------------------
   العمر: ١٥ — ٩٠ (و١٨+ = راشد)
   ------------------------------------------------------------ */
export const AGE_MIN = 15;
export const AGE_MAX = 90;
export const AGE_ADULT = 18;

export function ageNumber(value) {
  const d = digitsOnly(value);
  if (!d) return NaN;
  return Number(d);
}

export function isValidAge(value) {
  const age = ageNumber(value);
  return !isNaN(age) && age >= AGE_MIN && age <= AGE_MAX;
}

export function isAdult(value) {
  const age = ageNumber(value);
  return !isNaN(age) && age >= AGE_ADULT && age <= AGE_MAX;
}

/* ------------------------------------------------------------
   الأسماء
   ------------------------------------------------------------ */
export function isValidName(value) {
  const name = cleanText(value);
  if (name.length < 2 || name.length > 40) return false;
  /* حروف عربية أو لاتينية، وممنوع الأرقام والرموز */
  return /^[A-Za-z\u0621-\u064A]+(?:[ '\u0640-][A-Za-z\u0621-\u064A]+)*$/.test(name);
}

/* ------------------------------------------------------------
   العنوان
   ------------------------------------------------------------ */
export const CITY_MIN = 2;
export const POSTAL_LENGTH = 5;

export function isValidPostalCode(value) {
  const d = digitsOnly(value);
  return d.length === POSTAL_LENGTH;
}

export function validateAddress(address) {
  const a = address || {};
  const errors = {};

  if (!cleanText(a.city)) errors.city = "المدينة مطلوبة.";
  else if (cleanText(a.city).length < CITY_MIN) errors.city = "اسم المدينة قصير جداً.";

  if (!cleanText(a.district)) errors.district = "المنطقة مطلوبة.";
  else if (cleanText(a.district).length < CITY_MIN) errors.district = "اسم المنطقة قصير جداً.";

  if (!cleanText(a.street)) errors.street = "اسم الشارع مطلوب.";
  else if (cleanText(a.street).length < 3) errors.street = "اسم الشارع قصير جداً.";

  const building = digitsOnly(a.building);
  if (!building) errors.building = "رقم المبنى مطلوب.";
  else if (building.length > 4) errors.building = "رقم المبنى غير صحيح.";
  else if (Number(building) === 0) errors.building = "رقم المبنى لا يكون صفراً.";

  if (!digitsOnly(a.postal)) errors.postal = "الرمز البريدي مطلوب.";
  else if (!isValidPostalCode(a.postal)) errors.postal = "الرمز البريدي " + POSTAL_LENGTH + " أرقام.";

  if (a.landmark && cleanText(a.landmark).length > 80) errors.landmark = "العلامة المميزة طويلة جداً.";
  if (a.notes && cleanText(a.notes).length > 200) errors.notes = "الملاحظات طويلة جداً (٢٠٠ حرف كحدّ أقصى).";
  if (a.type && ["home", "work", "other"].indexOf(a.type) === -1) errors.type = "نوع العنوان غير معروف.";

  return {
    valid: Object.keys(errors).length === 0,
    errors: errors,
    firstError: firstOf(errors, ["city", "district", "street", "building", "postal", "landmark", "notes"])
  };
}

/* ------------------------------------------------------------
   نوع العقار في عنوان التوصيل (يستعمله Checkout — بدل «أقرب معلَم»).
   landmark القديم يبقى في validateAddress لحسابي، وهذا للطلبات الجديدة.
   ------------------------------------------------------------ */
export const PROPERTY_TYPES = [
  { key: "apartment", label: "شقة" },
  { key: "villa", label: "فيلا" },
  { key: "office", label: "مكتب" },
  { key: "shop", label: "محل تجاري" },
  { key: "other", label: "أخرى" }
];

export function propertyLabelOf(value) {
  const s = String(value == null ? "" : value);
  for (let i = 0; i < PROPERTY_TYPES.length; i++) {
    if (PROPERTY_TYPES[i].key === s) return PROPERTY_TYPES[i].label;
  }
  return s;
}

/* رمز الهاتف الافتراضي للدولة المختارة في Checkout (الدولة = مفتاح AE/…) */
const PHONE_CODE_BY_REGION = { AE: "971", SA: "966", KW: "965", BH: "973", OM: "968", QA: "974" };

export function phoneCodeOfRegion(region) {
  const s = String(region == null ? "" : region).trim().toUpperCase();
  return PHONE_CODE_BY_REGION[s] || "971";
}

/* ------------------------------------------------------------
   عنوان التوصيل في Checkout (النموذج الجديد):
     الاسم الأول · الاسم الثاني · الجوال + الدولة · المدينة · المنطقة ·
     الشارع (مطلوب — الخادم يرفض بدونه) · اسم المبنى ·
     الرمز البريدي (اختياري) · نوع العقار · ملاحظات للمندوب (تبقى).
   ★ validateAddress القديم يبقى لحسابي كما هو — هذا للطلب فقط.
   ------------------------------------------------------------ */
export function validateDelivery(values) {
  const v = values || {};
  const errors = {};
  const code = phoneCodeOfRegion(v.region);

  if (!cleanText(v.firstName)) errors.firstName = "الاسم الأول مطلوب.";
  else if (!isValidName(v.firstName)) errors.firstName = "الاسم الأول غير صحيح.";

  if (!cleanText(v.lastName)) errors.lastName = "الاسم الثاني مطلوب.";
  else if (!isValidName(v.lastName)) errors.lastName = "الاسم الثاني غير صحيح.";

  if (!phoneLocalDigits(code, v.phone)) errors.phone = "رقم الجوال مطلوب.";
  else if (!isValidPhoneFor(code, v.phone)) errors.phone = "رقم الجوال غير صحيح للدولة المختارة.";

  if (!cleanText(v.region)) errors.region = "اختر الدولة.";

  if (!cleanText(v.city)) errors.city = "المدينة مطلوبة.";
  else if (cleanText(v.city).length < CITY_MIN) errors.city = "اسم المدينة قصير جداً.";

  if (!cleanText(v.district)) errors.district = "المنطقة مطلوبة.";
  else if (cleanText(v.district).length < CITY_MIN) errors.district = "اسم المنطقة قصير جداً.";

  if (!cleanText(v.street)) errors.street = "اسم الشارع مطلوب.";
  else if (cleanText(v.street).length < 3) errors.street = "اسم الشارع قصير جداً.";

  if (!cleanText(v.building)) errors.building = "اسم المبنى مطلوب.";
  else if (cleanText(v.building).length < 2) errors.building = "اسم المبنى قصير جداً.";
  else if (cleanText(v.building).length > 60) errors.building = "اسم المبنى طويل جداً.";

  if (cleanText(v.postal)) {
    const p = cleanText(v.postal).replace(/[\s-]+/g, "");
    if (p.length < 3 || p.length > 10 || !/^[A-Za-z0-9]+$/.test(p)) errors.postal = "الرمز البريدي غير صحيح.";
  }

  if (!cleanText(v.propertyType)) errors.propertyType = "اختر نوع العقار.";
  else {
    let ok = false;
    for (let i = 0; i < PROPERTY_TYPES.length; i++) {
      if (PROPERTY_TYPES[i].key === String(v.propertyType)) {
        ok = true;
        break;
      }
    }
    if (!ok) errors.propertyType = "نوع العقار غير معروف.";
  }

  if (v.notes && cleanText(v.notes).length > 200) errors.notes = "الملاحظات طويلة جداً (٢٠٠ حرف كحدّ أقصى).";

  return {
    valid: Object.keys(errors).length === 0,
    errors: errors,
    firstError: firstOf(errors, ["firstName", "lastName", "phone", "region", "city", "district", "street", "building", "postal", "propertyType", "notes"])
  };
}
/* ------------------------------------------------------------
   الملف الشخصي الكامل — كل حقوله مطلوبة (باستثناء اللغة/العملة
   فلهما افتراض دائم). لا عمر بعد الآن: حُذف واستُبدل بمصدر الهاتف.
   ------------------------------------------------------------ */
export function validateProfile(profile) {
  const p = profile || {};
  const errors = {};

  if (!cleanText(p.firstName)) errors.firstName = "الاسم الأول مطلوب.";
  else if (!isValidName(p.firstName)) errors.firstName = "الاسم الأول غير صحيح.";

  if (!cleanText(p.lastName)) errors.lastName = "اسم العائلة مطلوب.";
  else if (!isValidName(p.lastName)) errors.lastName = "اسم العائلة غير صحيح.";

  if (!cleanText(p.email)) errors.email = "الإيميل مطلوب.";
  else if (!isValidEmail(p.email)) errors.email = "صيغة الإيميل غير صحيحة.";

  if (!phoneLocalDigits(p.phoneCode, p.phone)) errors.phone = "رقم الجوال مطلوب.";
  else if (!isValidPhoneFor(p.phoneCode, p.phone)) errors.phone = "رقم الجوال غير صحيح لمصدر الهاتف المختار.";

  if (!cleanText(p.region)) errors.region = "الدولة مطلوبة.";

  if (p.language && ["ar", "en"].indexOf(p.language) === -1) errors.language = "اللغة غير مدعومة.";
  if (p.currency && !/^[A-Z]{3}$/.test(String(p.currency))) errors.currency = "العملة غير صحيحة.";

  return {
    valid: Object.keys(errors).length === 0,
    errors: errors,
    firstError: firstOf(errors, ["firstName", "lastName", "email", "phone", "region"])
  };
}

/* ------------------------------------------------------------
   كشف حساب العميل الجديد/المؤقت — القيم القادمة من الـ API أحياناً
   صفٌّ مؤقت (عميل/جديد/زائر…) فيُعامل كأنه فارغ: لا يُعبَّأ في الحقول.
   ★ مطابقة بالكلمة الكاملة (tokens) حتى لا يُرفض «الجديد» الحقيقي.
   ------------------------------------------------------------ */
const PLACEHOLDER_NAME_TOKENS = [
  "عميل", "جديد", "زائر", "مستخدم", "مجهول", "مؤقت", "تجربة",
  "new", "guest", "user", "customer", "test", "unknown", "temp", "demo"
];

export function isPlaceholderName(value) {
  const s = cleanText(value).toLowerCase();
  if (!s) return true;
  const toks = s.split(/[\s\-_]+/);
  for (let i = 0; i < toks.length; i++) {
    if (PLACEHOLDER_NAME_TOKENS.indexOf(toks[i]) !== -1) return true;
  }
  return false;
}

export function isPlaceholderPhone(value) {
  const d = digitsOnly(value);
  if (!d || d.length < 7) return true;
  if (/^(\d)\1+$/.test(d)) return true;
  if ("0123456789".indexOf(d) !== -1 || "9876543210".indexOf(d) !== -1) return true;
  return false;
}

/* حساب جديد؟ (لا صفّ · غير مكتمل · أسماء مؤقتة · بلا اسم · هاتف عشوائي) */
export function isNewCustomerProfile(d) {
  if (!d) return true;
  if (d.isProfileComplete === false) return true;
  const fn = String(d.firstName || "");
  const ln = String(d.lastName || "");
  if (isPlaceholderName(fn) || isPlaceholderName(ln)) return true;
  if (!cleanText(fn) || !cleanText(ln)) return true;
  if (isPlaceholderPhone(d.phoneNumber != null ? d.phoneNumber : d.phone)) return true;
  return false;
}

/* ------------------------------------------------------------
   تسجيل الدخول / إنشاء حساب
   ------------------------------------------------------------ */
export function validateLogin(values) {
  const v = values || {};
  const errors = {};
  if (!cleanText(v.email)) errors.email = "أدخل إيميلك.";
  else if (!isValidEmail(v.email)) errors.email = "صيغة الإيميل غير صحيحة.";
  if (!String(v.password || "")) errors.password = "أدخل كلمة المرور.";
  return { valid: Object.keys(errors).length === 0, errors: errors, firstError: firstOf(errors, ["email", "password"]) };
}

/* ★ التسجيل المختصر: بريد + كلمة مرور + تأكيد + موافقة فقط.
   الاسم/الجوال/العمر/العنوان تُطلب عند تأكيد الطلب (CheckoutPage). */
export function validateRegister(values) {
  const v = values || {};
  const errors = {};

  if (!cleanText(v.email)) errors.email = "الإيميل مطلوب.";
  else if (!isValidEmail(v.email)) errors.email = "صيغة الإيميل غير صحيحة.";

  const pwIssues = passwordIssues(v.password);
  if (pwIssues.length) errors.password = pwIssues[0];
  if (String(v.confirm || "") !== String(v.password || "")) errors.confirm = "كلمتا المرور غير متطابقتين.";
  if (v.agree !== true) errors.agree = "يجب الموافقة على الشروط وسياسة الخصوصية.";

  return {
    valid: Object.keys(errors).length === 0,
    errors: errors,
    firstError: firstOf(errors, ["email", "password", "confirm", "agree"])
  };
}

/* ------------------------------------------------------------
   تقييم / تعليق
   ------------------------------------------------------------ */
export function validateReview(values) {
  const v = values || {};
  const errors = {};
  const rating = Number(v.rating) || 0;
  if (rating < 1 || rating > 5) errors.rating = "اختر عدد النجوم من ١ إلى ٥.";
  if (!cleanText(v.name)) errors.name = "اكتب اسمك (أو لقبك).";
  else if (cleanText(v.name).length < 2) errors.name = "الاسم قصير جداً.";
  else if (cleanText(v.name).length > 40) errors.name = "الاسم طويل جداً.";
  if (!cleanText(v.text)) errors.text = "اكتب تقييمك.";
  else if (cleanText(v.text).length < 8) errors.text = "اكتب ٨ أحرف على الأقل.";
  else if (cleanText(v.text).length > 800) errors.text = "النصّ طويل جداً (٨٠٠ حرف كحدّ أقصى).";
  return { valid: Object.keys(errors).length === 0, errors: errors, firstError: firstOf(errors, ["rating", "name", "text"]) };
}

/* ------------------------------------------------------------
   رسالة تواصل
   ------------------------------------------------------------ */
export function validateContact(values) {
  const v = values || {};
  const errors = {};
  if (!cleanText(v.name)) errors.name = "اكتب اسمك.";
  else if (!isValidName(v.name)) errors.name = "الاسم غير صحيح.";
  if (!cleanText(v.email)) errors.email = "الإيميل مطلوب.";
  else if (!isValidEmail(v.email)) errors.email = "صيغة الإيميل غير صحيحة.";
  if (cleanText(v.phone) && !isValidPhone(v.phone)) errors.phone = "رقم الجوال غير صحيح.";
  if (!cleanText(v.message)) errors.message = "اكتب رسالتك.";
  else if (cleanText(v.message).length < 10) errors.message = "اكتب ١٠ أحرف على الأقل.";
  else if (cleanText(v.message).length > 1000) errors.message = "الرسالة طويلة جداً.";
  return { valid: Object.keys(errors).length === 0, errors: errors, firstError: firstOf(errors, ["name", "email", "phone", "message"]) };
}

/* ------------------------------------------------------------
   كوبون الخصم: لا فراغات، حروف وأرقام فقط
   ------------------------------------------------------------ */
export function isValidCouponFormat(value) {
  return /^[A-Za-z0-9-]{3,20}$/.test(String(value || "").trim());
}

/* ------------------------------------------------------------
   أدوات مشتركة
   ------------------------------------------------------------ */
function firstOf(errors, order) {
  for (let i = 0; i < order.length; i++) {
    if (errors[order[i]]) return errors[order[i]];
  }
  const keys = Object.keys(errors);
  return keys.length ? errors[keys[0]] : "";
}

/* كل الرسائل مجتمعة (للعرض في رسالة واحدة) */
export function allMessages(result) {
  const errors = (result && result.errors) || {};
  return Object.keys(errors).map(function (k) {
    return errors[k];
  });
}

/* ملخّص جاهز للتنبيه */
export function firstError(result) {
  return (result && result.firstError) || "";
}

/* ============================================================
   بطاقة الدفع: الرقم · الانتهاء · رمز التحقق · حوالة · محفظة
   ------------------------------------------------------------
   كل ما هنا رياضيات خالصة بلا شبكة: لا نُرسل رقم بطاقة إلى أي مكان،
   ولا نحفظه. الخانة الوحيدة التي تُقرأ هي آخر أربع أرقام (للعرض).
   ============================================================ */

/* خوارزمية لُهن — الفحص الذي تُجرّبه كل بوابات الدفع قبل أي شيء آخر */
export function luhnValid(digits) {
  const d = digitsOnly(digits);
  if (d.length < 12) return false;
  let sum = 0;
  let double = false;
  for (let i = d.length - 1; i >= 0; i--) {
    let n = Number(d.charAt(i));
    if (double) {
      n *= 2;
      if (n > 9) n -= 9;
    }
    sum += n;
    double = !double;
  }
  return sum % 10 === 0;
}

/* نوع البطاقة من أول أرقامها (للعرض فقط — لا يغيّر صحّة الرقم) */
const CARD_BRANDS = [
  { key: "mada", label: "Mada", re: /^(4(0(0861|1757|1584))|9682|5297|2223)/ },
  { key: "visa", label: "Visa", re: /^4/ },
  { key: "mastercard", label: "Mastercard", re: /^(5[1-5]|2[2-7])/ },
  { key: "amex", label: "American Express", re: /^3[47]/ }
];

export function cardBrandOf(value) {
  const d = digitsOnly(value);
  for (let i = 0; i < CARD_BRANDS.length; i++) {
    if (CARD_BRANDS[i].re.test(d)) return CARD_BRANDS[i];
  }
  return { key: "unknown", label: "" };
}

/* تنسيق الرقم أثناء الكتابة: 4 4 4 4 (و6 لبطاقات أمريكان إكسبريس) */
export function formatCardNumber(value) {
  const d = digitsOnly(value).slice(0, 19);
  const brand = cardBrandOf(d);
  if (brand.key === "amex") return d.replace(/^(\d{0,4})(\d{0,6})(\d{0,5}).*$/, function (m, a, b, c) {
    return [a, b, c].filter(Boolean).join(" ");
  });
  const groups = [];
  for (let i = 0; i < d.length; i += 4) groups.push(d.slice(i, i + 4));
  return groups.join(" ");
}

export function isValidCardNumber(value) {
  const d = digitsOnly(value);
  return d.length >= 13 && d.length <= 19 && luhnValid(d);
}

/* آخر أربع أرقام — كل ما نعرضه في الفاتورة (لا نحفظ الرقم كاملاً) */
export function cardLast4(value) {
  const d = digitsOnly(value);
  return d.length >= 4 ? d.slice(-4) : "";
}

const MONTHS_MAX = 12;
const EXPIRY_YEARS_AHEAD = 20;

/* MM/YY — ولا نقبل شهراً مضى (شهر اليوم نفسه ما زال صالحاً) */
export function isValidExpiry(value) {
  const d = digitsOnly(value);
  if (d.length !== 4) return false;
  const month = Number(d.slice(0, 2));
  const year = 2000 + Number(d.slice(2));
  if (month < 1 || month > MONTHS_MAX) return false;
  const now = new Date();
  if (year < now.getFullYear() || year > now.getFullYear() + EXPIRY_YEARS_AHEAD) return false;
  if (year === now.getFullYear() && month < now.getMonth() + 1) return false;
  return true;
}

/* تاريخ الانتهاء نصّاً بصيغة MM/YY أثناء الكتابة */
export function formatExpiry(value) {
  const d = digitsOnly(value).slice(0, 4);
  if (d.length <= 2) return d;
  return d.slice(0, 2) + " / " + d.slice(2);
}

/* رمز التحقق: ٣ أرقام (٤ لأمريكان إكسبريس) */
export function isValidCvv(value, brandKey) {
  const d = digitsOnly(value);
  const need = brandKey === "amex" ? 4 : 3;
  return d.length === need;
}

/* ------------------------------------------------------------
   الحوالة البنكية: رقم الآيبان (بصيغة دولية + فحص mod-97 حقيقي)
   ------------------------------------------------------------ */
const IBAN_LENGTHS = { SA: 24, AE: 23, KW: 30, BH: 22, OM: 23, QA: 29, JO: 30, EG: 29 };

export function formatIban(value) {
  return String(normalizeDigits(value) || "")
    .replace(/[^A-Za-z0-9]/g, "")
    .toUpperCase()
    .replace(/(.{4})/g, "$1 ")
    .trim();
}

export function isValidIban(value) {
  const iban = String(normalizeDigits(value) || "")
    .replace(/[^A-Za-z0-9]/g, "")
    .toUpperCase();
  const country = iban.slice(0, 2);
  if (!IBAN_LENGTHS[country] || iban.length !== IBAN_LENGTHS[country]) return false;
  if (!/^[A-Z]{2}\d{2}[A-Z0-9]+$/.test(iban)) return false;
  /* فحص mod-97: ننقل أول أربعة أحرف إلى النهاية ونحوّل الحروف إلى أرقام */
  const rearranged = iban.slice(4) + iban.slice(0, 4);
  let rem = 0;
  for (let i = 0; i < rearranged.length; i++) {
    const ch = rearranged.charAt(i);
    const num = ch >= "A" && ch <= "Z" ? String(ch.charCodeAt(0) - 55) : ch;
    for (let j = 0; j < num.length; j++) rem = (rem * 10 + Number(num.charAt(j))) % 97;
  }
  return rem === 1;
}

/* ------------------------------------------------------------
   خطوات إتمام الدفع — تحقّق مركزي واحد يخدم الخطوات الثلاث
   ★ يقبل نفس حقول نموذج العنوان (city/district/…) فيستدعي
     validateAddress بدل تكرار منطقها.
   ------------------------------------------------------------ */
export function stepErrors(values, step) {
  const v = values || {};
  const method = String(v.method || "");
  const errors = {};

  if (step === "info" || step === "review") {
    const delivery = validateDelivery(v);
    Object.keys(delivery.errors).forEach(function (k) {
      errors[k] = delivery.errors[k];
    });
  }

  if (step === "pay" || step === "review") {
    if (!method) {
      errors.method = "اختر طريقة الدفع أولاً";
    } else if (method === "transfer") {
      if (v.transferAck !== true) errors.transferAck = "أكّد أنك ستُحوّل المبلغ لإتمام الطلب.";
    }
  }

  if (step === "review") {
    if (v.agree !== true) errors.agree = "يجب الموافقة على الشروط قبل تأكيد الطلب.";
  }

  return errors;
}

/* نتيجة كاملة لخطوة واحدة: { valid, errors, firstError } */
export function validateStep(values, step) {
  const errors = stepErrors(values, step);
  const order =
    step === "info"
      ? ["firstName", "lastName", "phone", "region", "city", "district", "street", "building", "postal", "propertyType", "notes"]
      : step === "pay"
        ? ["method", "transferAck"]
        : ["agree", "firstName", "lastName", "phone", "region", "city", "district", "street", "building", "postal", "propertyType", "notes", "method", "transferAck"];
  return { valid: Object.keys(errors).length === 0, errors: errors, firstError: firstOf(errors, order) };
}

/* كل الحقول مرة واحدة (يستعملها الاختبار أو أي بوابة مستقبلية) */
export function validateCheckout(values) {
  const merged = Object.assign({}, stepErrors(values, "info"), stepErrors(values, "pay"), stepErrors(values, "review"));
  return { valid: Object.keys(merged).length === 0, errors: merged, firstError: firstOf(merged, Object.keys(merged)) };
}
