/* ============================================================
   أطياب الجاسم (React) — عرض السعر والنجوم

   ★ السعر لا يُحسب هنا: نُمرّر الرقم المخزّن (بالدرهم الإماراتي —
     عملة الأساس) إلى خطّاف useMoney (selectors) فيُحوّله إلى العملة
     التي اختارها العميل في ملفه الشخصي، ويرسم رمز العملة داخل <small>
     في موضعه الصحيح (بعد الرقم عربياً، وقبله في الدولار).

   <Money sar={99} />         →  99.00 <small>د.إ</small>
   <Stars rating={4.8} />     →  نجمة ممتلئة جزئياً حسب التقييم
   ============================================================ */

import { useMoney } from "../../redux/selectors.js";
import { Icon } from "./Icons.jsx";

/* سعر بواحد/عدة أسعار (total = السعر × الكمية اختيارياً) */
export function Money(props) {
  const money = useMoney();
  const parts = money.parts(props.sar);
  return (
    <span className={props.className}>
      {parts.before ? (
        <>
          <small>{parts.symbol}</small>
          {parts.symbol.length > 1 ? " " : ""}
          {parts.value}
        </>
      ) : (
        <>
          {parts.value} <small>{parts.symbol}</small>
        </>
      )}
    </span>
  );
}

/* مبلغ بلا رمز (نستخدمه في الأرقام الكبيرة داخل العروض) */
export function MoneyAmount(props) {
  const money = useMoney();
  return <span className={props.className}>{money.amount(props.sar)}</span>;
}

/* نجوم التقييم: طبقة رمادية + طبقة ذهبية مقصوصة بنسبة التقييم */
export function Stars(props) {
  const rating = Math.max(0, Math.min(5, Number(props.rating) || 0));
  const pct = ((rating / 5) * 100).toFixed(1) + "%";
  const className = props.className || "pd-stars";
  const row = props.rowClass || "pd-stars-row";
  const base = props.baseClass || "pd-stars-base";
  const fill = props.fillClass || "pd-stars-fill";
  const n = 5;
  const stars = [];
  for (let i = 0; i < n; i++) stars.push(i);
  return (
    <span className={className} role="img" aria-label={"التقييم " + rating + " من 5"}>
      <span className={row + " " + base}>
        {stars.map(function (i) {
          return <Icon key={i} name="star" fill="currentColor" strokeWidth={0} />;
        })}
      </span>
      <span className={row + " " + fill} style={{ width: pct }}>
        {stars.map(function (i) {
          return <Icon key={i} name="star" fill="currentColor" strokeWidth={0} />;
        })}
      </span>
    </span>
  );
}
