/* ============================================================
   أطياب الجاسم (React) — جذر التطبيق (App)

   نفس بنية المشروع المرجعي بالضبط:
     <HashRouter>  ← الراوتر الوحيد للموقع (لا قراءة/كتابة hash يدوياً)
       <Routes>
         · مسار التخطيط العام (MainLayout) يغلّف كل الصفحات التي يظهر
           فيها الهيدر والفوتر، والصفحة النشطة تُرسم داخله بـ<Outlet />.
         · كل صفحة لها <Route> واحد بمسارها كما في المرجع.
         · صفحات الدخول/التسجيل خارج التخطيط (كصفحة Login في المرجع).

   ★ App لا يعرف شيئاً عن محتوى الصفحات: لا props، ولا حالة، ولا عنوان
     تبويب — كل صفحة تستدعي ما تحتاجه بنفسها (usePageMeta · useSelector
     · useEffect) وتُصرّح عن مسارها في السطور أدناه فقط.
   ============================================================ */

import { useEffect, useRef } from "react";
import { HashRouter, Routes, Route, Navigate } from "react-router-dom";
import { useAppDispatch, useAppSelector } from "./redux/hooks.js";
import { getStoreSettings, selectStoreSettings, selectSupport } from "./redux/slices/settingsSlice.js";
import { pullBasket } from "./redux/slices/cartSlice.js";
import { pullWishlist } from "./redux/slices/wishlistSlice.js";
import { uiActions } from "./redux/slices/uiSlice.js";
import { atyabLog } from "./redux/api.js";
import { bootAuth, authHeartbeat, ensureFreshToken, loadSession } from "./api/auth.js";
import { captureRefFromUrl } from "./api/affiliate.js";

import MainLayout from "./MainLayout.jsx";
import { PATHS } from "./routes.js";

/* الصفحات — كل واحدة ملف مستقل يستورد ما يحتاجه هو فقط.
   ★ الرئيسية (MainPage) ليست هنا: التخطيط العام يُركّبها دائماً داخل
     .route-slot ويُخفيها بـ[hidden]، فلا تُفكَّك عند التنقّل (وهو ما
     يُفقد مشهد المبخرة 3D وعرض العطور 2D حالتَهما). */
import PerfumePage from "./pages/PerfumePage.jsx";
import BakhourPage from "./pages/BakhourPage.jsx";
import OudsPage from "./pages/OudsPage.jsx";
import ShowProductDetailsPage from "./pages/ShowProductDetailsPage.jsx";
import OfferPage from "./pages/OfferPage.jsx";
import TrolleyPage from "./pages/TrolleyPage.jsx";
import CheckoutPage from "./pages/CheckoutPage.jsx";
import PaymentReturnPage from "./pages/PaymentReturnPage.jsx";
import PaymentRedirectPage from "./pages/PaymentRedirectPage.jsx";
import WishlistPage from "./pages/WishlistPage.jsx";
import UserInfoPage from "./pages/UserInfoPage.jsx";
import ContactUs from "./pages/ContactUs.jsx";
import SearchPage from "./pages/SearchPage.jsx";
import DeliveryPage from "./pages/DeliveryPage.jsx";
import BranchesPage from "./pages/BranchesPage.jsx";
import PaymentMethodPage from "./pages/PaymentMethodPage.jsx";
import InfoPage from "./pages/InfoPage.jsx";
import MaintenancePage from "./pages/MaintenancePage.jsx";

/* نافذة الدخول/التسجيل — صفحتان مستقلّتان بلا هيدر ولا فوتر */
import LogIn from "./components/Source/LogIn.jsx";

/* ★ بوابة المتجر: إن عطّل المالك المتجر (siteEnabled=false) لا يدخل أحد —
   شاشة فارغة: اللوجو في المنتصف وتحته رسالة الإغلاق بلغته */
function StoreGate(props) {
  const dispatch = useAppDispatch();
  const settings = useAppSelector(selectStoreSettings);
  const status = useAppSelector(function (s) { return (s.settings && s.settings.status) || "idle"; });
  const language = useAppSelector(function (s) { return s.ui.language; });
  const support = useAppSelector(selectSupport);

  useEffect(
    function () {
      atyabLog("settings BOOT");
      dispatch(getStoreSettings());
      /* ★ إحالة المؤثرين (§1): التقاط ?ref= مرة واحدة عند الإقلاع —
         يحفظ في localStorage (آخر رابط يفوز)، وتنقل الهاش لا يمسّه */
      try {
        const refCode = captureRefFromUrl();
        if (refCode) atyabLog("ref CAPTURED " + refCode);
      } catch (e) {
        /* بلا ref — عمل طبيعي */
      }
      /* ★ عودة الدفع الضائعة: الباك-اند قد يُعيد العميل إلى جذر الموقع
         (أو يعلّق ?cartId=/tranRef= قبل الـ# بدل داخلها) حين يكون
         StorefrontReturnUrl مضبوطاً خطأً — فنلتقط المرجع من عنوان
         المتصفح ونحوّله لمسار العودة الصحيح بدل صفحة فارغة بلا مرجع.
         العقد (§10): العودة تحمل ?cartId=AY-5-...
         ★ تحذير صريح: `ref` المجرد مستثنى عمداً — هو بارامتر الإحالة
         (§1) وليس مرجع بوابة، والتقاطه هنا كان يخطف كل زائر إحالة
         إلى صفحة الدفع. لا تُعِده إلى هذه القائمة تحت أي ظرف. */
      try {
        const qs = String(window.location.search || "");
        const hasPayRef = /[?&](cartId|cart_id|tranRef|tran_ref|tranref|merchantReference|merchant_reference|merchantRef|reference)=/i.test(qs);
        const hash = String(window.location.hash || "");
        const onReturn = hash.indexOf("#/payment/return") === 0 || hash.indexOf("#payment/return") === 0;
        if (hasPayRef && !onReturn) {
          atyabLog("payment RETURN-CATCH", qs);
          window.location.hash = "#/payment/return" + qs;
        }
      } catch (e) {
        /* بيئة بلا عنوان */
      }
      /* ★ دخول Guest فوراً، ثم تجديد صامت إلى Customer إن وُجد refresh */
      bootAuth(dispatch).then(function (mode) {
        atyabLog("auth BOOT " + mode);
      });
      /* ★ نبض التجديد الصامت + مقبض تصحيح للكونسول */
      try {
        window.__ATYAB_AUTH__ = {
          mode: function () {
            return loadSession();
          },
          refresh: function () {
            return ensureFreshToken();
          }
        };
      } catch (e) {
        /* تجاهل */
      }
      const beat = function () {
        authHeartbeat(dispatch);
      };
      const timer = window.setInterval(beat, 60000);
      const onVis = function () {
        if (!document.hidden) beat();
      };
      document.addEventListener("visibilitychange", onVis);
      return function () {
        window.clearInterval(timer);
        document.removeEventListener("visibilitychange", onVis);
      };
    },
    [dispatch]
  );

  /* ★ عضو مسجّل؟ سلة الخادم ومفضلته تُسحبان وتُدمجان مع المحلي —
     مرة واحدة لكل حساب (إقلاع + دخول)، والضيف لا يُمسّ */
  const customerId = useAppSelector(function (s) {
    return s.user.auth && s.user.auth.customerId;
  });
  const syncedFor = useRef(null);
  useEffect(
    function () {
      if (customerId) {
        if (syncedFor.current !== Number(customerId)) {
          syncedFor.current = Number(customerId);
          dispatch(pullBasket());
          dispatch(pullWishlist());
        }
      } else {
        syncedFor.current = null;
      }
    },
    [dispatch, customerId]
  );

  if (status === "succeeded" && settings && settings.siteEnabled === false) {
    const en = language === "en";
    const name = en ? settings.storeNameEn : settings.storeNameAr;
    const msg = en ? settings.offlineMessageEn : settings.offlineMessageAr;
    return (
      <div className="store-offline" role="status" aria-live="polite" style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", textAlign: "center", padding: "24px" }}>
        <div>
          <button
            type="button"
            className="store-offline-lang"
            style={{ marginBottom: "18px", background: "none", border: "1px solid currentColor", borderRadius: "999px", padding: "6px 18px", cursor: "pointer", opacity: 0.8 }}
            onClick={function () { dispatch(uiActions.setLanguage(en ? "ar" : "en")); }}
          >
            {en ? "العربية" : "English"}
          </button>
          <div className="store-offline-logo" style={{ fontSize: "34px", fontWeight: 800, marginBottom: "12px" }}>{name}</div>
          <p className="store-offline-msg" style={{ maxWidth: "420px", margin: "0 auto 16px", lineHeight: 1.9 }}>{msg}</p>
          <p className="store-offline-phone" dir="ltr" style={{ margin: "0 0 16px", fontSize: "18px", fontWeight: 700 }}>{support.phone}</p>
          <a className="btn-primary" href={"https://wa.me/" + support.whatsappDigits + "?text=" + encodeURIComponent(en ? "Hello, I found the store closed and would like to ask about it." : "السلام عليكم، وجدت المتجر مغلقاً وأريد الاستفسار.")} target="_blank" rel="noopener noreferrer">
            {en ? "Message us on WhatsApp" : "راسلنا على الواتساب"}
          </a>
        </div>
      </div>
    );
  }
  return props.children;
}

function App() {
  return (
    <HashRouter>
      <StoreGate>
      <Routes>
        {/* ============ التخطيط العام (هيدر + الصفحة + فوتر) ============ */}
        <Route path="/" element={<MainLayout />}>
          <Route index element={null} />
          <Route path="perfumes" element={<PerfumePage />} />
          <Route path="incense" element={<BakhourPage />} />
          <Route path="ouds" element={<OudsPage />} />
          <Route path="product/:id" element={<ShowProductDetailsPage />} />
          <Route path="offers" element={<OfferPage />} />
          <Route path="cart" element={<TrolleyPage />} />
          <Route path="checkout" element={<CheckoutPage />} />
          <Route path="payment/return" element={<PaymentReturnPage />} />
          <Route path="payment/start" element={<PaymentRedirectPage />} />
          <Route path="wishlist" element={<WishlistPage />} />
          <Route path="profile" element={<UserInfoPage />} />
          <Route path="contact" element={<ContactUs />} />
          <Route path="search" element={<SearchPage />} />
          <Route path="about" element={<InfoPage pageKey="about" />} />
          <Route path="shipping" element={<DeliveryPage />} />
          <Route path="branches" element={<BranchesPage />} />
          <Route path="payments" element={<PaymentMethodPage />} />
          <Route path="legal" element={<InfoPage pageKey="legal" />} />

          {/* محرّر المنصّة يضيف #edit لرابط المعاينة — نتجاهله */}
          <Route path="edit/*" element={<Navigate to={PATHS.perfumes} replace />} />

          {/* صفحة «قيد الصيانة»: لأي مسار غير معروف، واسمه يُقرأ من الرابط */}
          <Route path="maintenance" element={<MaintenancePage />} />
          <Route path="maintenance/:key" element={<MaintenancePage />} />
          <Route path="*" element={<MaintenancePage />} />
        </Route>

        {/* ============ الدخول والتسجيل (صفحتان مستقلّتان) ============ */}
        <Route path={PATHS.login} element={<LogIn mode="login" />} />
        <Route path={PATHS.register} element={<LogIn mode="signup" />} />
      </Routes>
      </StoreGate>
    </HashRouter>
  );
}

export default App;
